import Avatar from "@mui/material/Avatar";
import { Link, Box } from '@mui/material';
import { Link as RouterLink } from 'react-router-dom';

function Header({user}) {
  console.log(user);
  
  return (
    <header className="h-20 px-6 bg-white border-b">

      <div className="grid grid-cols-3 h-full items-center">
        <Link 
          component={RouterLink} 
          to="/" 
          sx={{ display: 'flex', alignItems: 'center' }}
        >
          <Box
            component="img"
            src="/images/logo.png"
            alt="ChefGPT"
            sx={{ maxHeight: 'sd' }}
          />
        </Link>
       
        <h1 className="text-xl font-semibold text-center">Center</h1>

        <div className="text-right justify-self-end">
          <Avatar alt={user.nickname} src={user.picture} slotProps={{img: {draggable: false} }} sx={{ maxWidth: 'md' }}/>
        </div>
        {/* <h1 className="text-xl font-semibold text-right">Right</h1> */}
        
      </div>
    </header>
  );
}
export default Header;
